CREATE EXTENSION pageinspect;
SELECT level
FROM bt_metap('schueler_pkey');
-- level: 2

EXPLAIN (ANALYZE, BUFFERS)
SELECT * FROM schueler
WHERE id = 4242;
-- Index Scan using schueler_pkey
--   Index Cond: (id = 4242)
--   Buffers: shared hit=4

# Hashfunktion h(k) = k mod 4
buckets = {i: [] for i in range(4)}
for k in [17, 42, 8, 25, 33, 12]:
    buckets[k % 4].append(k)
print(buckets)
# {0: [8, 12], 1: [17, 25, 33],
#  2: [42], 3: []}

-- PostgreSQL
CREATE INDEX ix_plz ON schueler
  USING hash (plz);
-- plz = 1234      -> nutzt ix_plz
-- plz BETWEEN ... -> Seq Scan
